const s = $input.first().json;

const responseRate = (s.response_rate * 100).toFixed(1);
const offerRate    = (s.offer_rate    * 100).toFixed(1);

const blocks = [
  {
    type: 'header',
    text: { type: 'plain_text', text: '📋 Job Search Daily Digest', emoji: true }
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*Today's snapshot* — ${new Date().toDateString()}`
    }
  },
  { type: 'divider' },
  {
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: `*📨 Applied*\n${s.applied}` },
      { type: 'mrkdwn', text: `*🎤 Interview*\n${s.interview}` },
      { type: 'mrkdwn', text: `*🎉 Offer*\n${s.offer}` },
      { type: 'mrkdwn', text: `*❌ Rejected*\n${s.rejected}` }
    ]
  },
  {
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: `*📊 Response Rate*\n${responseRate}%` },
      { type: 'mrkdwn', text: `*✅ Offer Rate*\n${offerRate}%` }
    ]
  },
  s.needs_review > 0
    ? {
        type: 'section',
        text: {
          type: 'mrkdwn',
          text: `⚠️ *${s.needs_review} email(s) need manual review* — check your Notion review page.`
        }
      }
    : { type: 'divider' },
  {
    type: 'context',
    elements: [{ type: 'mrkdwn', text: 'Powered by Job Tracker Agent 🤖' }]
  }
];

return [{ json: { blocks } }];
